INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('89f60168-45f5-555a-a646-d1a013f5a0d7','07b49d3d-1ae7-5a34-961d-96d9aa0708bf','shared_external_bleeding','shared_external_bleeding','Chảy máu ngoài','ALL','Người lớn và trẻ em có vết thương ngoài da đang chảy máu. Không áp dụng cho chảy máu nội tạng, mắt, vết thương ngực/bụng hoặc vật đang cắm trong vết thương.','Dùng vật liệu sạch để tạo áp lực trực tiếp và tìm trợ giúp y tế sớm.','["Thấy máu chảy từ vết thương ngoài da."]'::jsonb,'["Chảy máu nhiều hoặc khó cầm: nhờ người gọi 115 ngay, đồng thời tiến hành cầm máu."]'::jsonb,'["Không tự rút vật đang cắm trong vết thương; không ép trực tiếp lên vật đó. Tìm trợ giúp y tế.","Không coi việc máu tạm ngừng là đã loại trừ tổn thương sâu.","Với trẻ em, luôn có người giám sát; không để trẻ ngậm hoặc gỡ gạc nhỏ cho vào miệng."]'::jsonb,'["Chảy máu nhiều, phun thành tia hoặc không kiểm soát được.","Vết thương sâu/rộng, có vật cắm, mất cảm giác hoặc khó vận động: cần đánh giá y tế khẩn.","Ở trẻ em, vẫn không cầm sau 5 phút ép trực tiếp cần gọi 115; chảy máu nặng phải gọi ngay, không chờ đủ thời gian."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('889ef399-c30e-5352-b4a1-20a8e03373c5','89f60168-45f5-555a-a646-d1a013f5a0d7',1,'Bảo vệ người trợ giúp','Đeo găng nếu có; dùng gạc hoặc vải sạch làm lớp ngăn giữa tay và máu.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('a2282571-a761-5f1e-a6f9-9668f2f214f5','89f60168-45f5-555a-a646-d1a013f5a0d7',2,'Ép trực tiếp','Nếu không có vật cắm trong vết thương, đặt gạc hoặc vải sạch lên chỗ chảy máu và ấn chắc, duy trì áp lực.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('3dbc88b2-ec34-5d9a-a3e6-b90f22b800f9','89f60168-45f5-555a-a646-d1a013f5a0d7',3,'Giữ gạc tại chỗ','Nếu máu thấm qua, thêm lớp gạc hoặc vải sạch lên trên và tiếp tục ép. Khi kiểm soát được máu, cố định gạc; không băng quá chặt.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('066e714b-b863-5cd0-a2e8-bd874a3cdd72','89f60168-45f5-555a-a646-d1a013f5a0d7',4,'Liên hệ hỗ trợ','Gọi 115 khi chảy máu nhiều hoặc chưa cầm được; tiếp tục giữ áp lực trong lúc chờ hướng dẫn và trợ giúp.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'89f60168-45f5-555a-a646-d1a013f5a0d7','0da603f1-f47f-5756-8179-90ff789e71f5',1,16,16,'all','Trang in 7, phần Trình tự cầm máu. Bổ sung kiểm tra trường hợp vật cắm, máu thấm gạc và dấu hiệu cần cấp cứu: NHS Cuts and grazes, https://www.nhs.uk/conditions/cuts-and-grazes/ (đọc 28/10/2026).');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'89f60168-45f5-555a-a646-d1a013f5a0d7','aa4dd01e-5118-53d9-92a7-5deed81dcf4c',2,NULL,NULL,'all','Nguồn bổ sung đối chiếu; không phải trang PDF.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'89f60168-45f5-555a-a646-d1a013f5a0d7','fec4959c-796a-5568-9dd2-f5cec7e945a0',3,39,44,'all','Các phần Tổng quan; Sử dụng băng, gạc; Gọi sự giúp đỡ (đặc biệt trang PDF 39–40, 41–42 và 44). Không dùng phần lượng giá. Ngoại lệ vật cắm đối chiếu NHS Cuts and grazes: https://www.nhs.uk/conditions/cuts-and-grazes/ (đọc 28/10/2026).');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('90ed2110-a47d-571f-8fc5-de491f084ce4','dab1b20c-fba7-5c3f-82f4-83ae17f9d626','shared_nosebleed','shared_nosebleed','Chảy máu cam','ALL','Người lớn và trẻ em còn tỉnh, tự ngồi và thở được, chảy máu từ mũi. Nếu sau chấn thương đầu, khó thở, yếu/chóng mặt hoặc máu chảy nhiều: tìm trợ giúp khẩn ngay.','Cúi đầu về trước và bóp phần mềm của mũi liên tục 10–15 phút.','["Máu chảy ra từ một hoặc hai bên mũi."]'::jsonb,'["Ngồi và cúi nhẹ về trước; thở bằng miệng."]'::jsonb,'["Không ngửa đầu ra sau.","Không tự lái xe đi cấp cứu khi yếu hoặc chóng mặt.","Trấn an và hỗ trợ trẻ giữ tư thế, không ngoáy hoặc xì mũi ngay sau cầm máu."]'::jsonb,'["Máu không ngừng sau 10–15 phút.","Chảy máu nhiều, nuốt nhiều máu gây nôn, khó thở, yếu/chóng mặt hoặc chấn thương đầu: cần cấp cứu.","Đang dùng thuốc chống đông hoặc chảy máu tái diễn: cần được nhân viên y tế đánh giá.","Trẻ dưới 2 tuổi bị chảy máu cam cần được bác sĩ đánh giá."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('02331200-71a8-5408-8a79-9ffa59df13fa','90ed2110-a47d-571f-8fc5-de491f084ce4',1,'Ngồi, cúi về trước','Ngồi thẳng, đầu hơi cúi về trước, mở miệng và thở bằng miệng.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('1a7bcaee-c230-508a-b071-0c3f6cfe502d','90ed2110-a47d-571f-8fc5-de491f084ce4',2,'Bóp phần mềm của mũi','Dùng ngón cái và ngón trỏ bóp phần mềm ngay trên lỗ mũi, giữ liên tục 10–15 phút.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('6a7dec68-715e-5fbf-b799-096c97365223','90ed2110-a47d-571f-8fc5-de491f084ce4',3,'Kiểm tra và tìm trợ giúp','Sau 10–15 phút, nếu vẫn chảy máu, đến cơ sở y tế. Nếu máu chảy nhiều, khó thở, yếu/chóng mặt hoặc xảy ra sau va đập đầu: gọi 115 hoặc nhờ đưa đi cấp cứu, không chờ hết thời gian.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'90ed2110-a47d-571f-8fc5-de491f084ce4','0da603f1-f47f-5756-8179-90ff789e71f5',1,16,16,'all','Trang in 7, mục Xử lý chảy máu mũi đúng cách. Thời gian bóp liên tục và tiêu chí tìm trợ giúp bổ sung từ NHS Nosebleed: https://www.nhs.uk/conditions/nosebleed/ (đọc 28/10/2026); số gọi được địa phương hóa thành 115.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'90ed2110-a47d-571f-8fc5-de491f084ce4','d20a77a6-beeb-5424-9134-be3b2b5cc685',2,NULL,NULL,'all','Nguồn bổ sung đối chiếu; không phải trang PDF.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'90ed2110-a47d-571f-8fc5-de491f084ce4','fec4959c-796a-5568-9dd2-f5cec7e945a0',3,52,53,'all','Có mục chảy máu mũi nhưng tư thế ngửa đầu không dùng; giữ phần theo dõi/chăm sóc.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'90ed2110-a47d-571f-8fc5-de491f084ce4','0da603f1-f47f-5756-8179-90ff789e71f5',4,16,16,'all','Tư thế cúi về trước.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'90ed2110-a47d-571f-8fc5-de491f084ce4','d20a77a6-beeb-5424-9134-be3b2b5cc685',5,NULL,NULL,'all','Nguồn quyết định tư thế cúi, giữ 10–15 phút và tiêu chí đi khám.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('ee664152-773b-59c8-bc4c-20500943f447','7cf89dce-4b3e-5060-8173-af30dcbf1fa1','shared_minor_thermal_burn','shared_minor_thermal_burn','Bỏng nhiệt nhẹ','ALL','Người lớn và trẻ em bị bỏng nhiệt nhỏ do nước/vật nóng, da chưa tróc. Không áp dụng cho nhũ nhi, bỏng điện/hóa chất, bỏng rộng/sâu, ở mặt hoặc vùng sinh dục; cần trợ giúp y tế cho các trường hợp đó.','Ngừng tiếp xúc với nguồn nhiệt, làm mát 20 phút, che bảo vệ và tìm tư vấn y tế.','["Vùng da sau tiếp xúc nguồn nóng bị đỏ, đau rát; bài này chỉ dành cho diện tích nhỏ, chưa tróc da."]'::jsonb,'["Đưa người bị bỏng khỏi tác nhân nóng nếu an toàn; bắt đầu làm mát ngay."]'::jsonb,'["Không bôi dầu mỡ, cồn hoặc kem kháng sinh lên vết bỏng.","Không chọc vỡ bóng nước, bóc da hoặc quần áo dính.","Không lấy quy trình này thay cho xử trí bỏng điện/hóa chất; không tự dùng thuốc hoặc dung dịch bù dịch."]'::jsonb,'["Bỏng ở trẻ em cần tư vấn y tế; không dựa vào giảm đau để kết luận đã an toàn.","Bỏng nặng, rộng/sâu, mặt/vùng sinh dục hoặc điện/hóa chất: cần cấp cứu."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('9b7b1677-d7c0-56e1-a547-764f2df5080a','ee664152-773b-59c8-bc4c-20500943f447',1,'Ngừng tác nhân nóng','Đảm bảo an toàn rồi đưa người bị bỏng khỏi vật/nước nóng. Tháo trang sức và quần áo gần vùng bỏng nếu không dính; không bóc vật dính trên da.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('bb64893c-84dc-5bf7-aec3-0e87705f0dd7','ee664152-773b-59c8-bc4c-20500943f447',2,'Làm mát 20 phút','Làm mát vùng bỏng nhỏ bằng nước sạch mát trong 20 phút. Giữ ấm những phần cơ thể không bị bỏng.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('99da0ddc-4089-5bdf-a23b-d844e7548e42','ee664152-773b-59c8-bc4c-20500943f447',3,'Che bảo vệ','Sau làm mát, phủ nhẹ bằng gạc vô khuẩn hoặc vải sạch; không dán băng dính trực tiếp vào vùng bỏng.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('0c2e2de4-16f4-55c6-89b4-071301575838','ee664152-773b-59c8-bc4c-20500943f447',4,'Nhờ nhân viên y tế','Tìm tư vấn y tế, đặc biệt khi người bị bỏng là trẻ em. Gọi 115 hoặc nhờ đưa đi cấp cứu khi bỏng rộng/sâu, bỏng ở mặt/vùng sinh dục, do điện/hóa chất hoặc có dấu hiệu nặng.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'ee664152-773b-59c8-bc4c-20500943f447','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,86,88,'all','Phần II Bỏng; hướng dẫn và lưu ý ở trang PDF 87. Giới hạn làm mát theo nguồn: bỏng nhẹ, chưa tróc da. Bổ sung: NHS Burns and scalds https://www.nhs.uk/conditions/burns-and-scalds/; British Red Cross Burns in babies and children https://www.redcross.org.uk/first-aid/learn-first-aid-for-babies-and-children/burns (đối chiếu 28/10/2026).');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'ee664152-773b-59c8-bc4c-20500943f447','b24ed962-8160-580d-bd5f-4c442ee85e83',2,NULL,NULL,'all','Nguồn bổ sung đối chiếu; không phải trang PDF.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'ee664152-773b-59c8-bc4c-20500943f447','0da603f1-f47f-5756-8179-90ff789e71f5',3,35,37,'all','Loại phần tự bù dịch; không áp dụng quy trình chung cho mọi tác nhân.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'ee664152-773b-59c8-bc4c-20500943f447','b24ed962-8160-580d-bd5f-4c442ee85e83',4,NULL,NULL,'all','Đối chiếu quần áo dính, che phủ và dấu hiệu cần cấp cứu.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('358c7197-a3b5-5d61-b225-cc087be9800a','8210e0ee-f553-5cb0-a771-2183105cd661','shared_unresponsive','shared_unresponsive','Không đáp ứng: kiểm tra và gọi trợ giúp','ALL','Người lớn và trẻ em không đáp ứng khi gọi hỏi. Không mặc định họ đang ngủ hoặc đã ổn.','Đảm bảo an toàn và gọi 115 ngay; bật loa ngoài để nhận hướng dẫn.','["Gọi lớn và chạm nhẹ vai nhưng người đó không trả lời hoặc không có phản ứng."]'::jsonb,'["Đảm bảo an toàn và gọi 115 ngay; bật loa ngoài để nhận hướng dẫn."]'::jsonb,'["Không cho ăn, uống hay nhét vật vào miệng.","Không đặt nằm nghiêng người đang thở ngáp thay cho CPR."]'::jsonb,'["Mọi trường hợp không đáp ứng đều cần gọi 115."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('4a7e8fe5-c7d5-57c9-91f3-70e2b7f7320e','358c7197-a3b5-5d61-b225-cc087be9800a',1,'Tiếp cận an toàn','Kiểm tra nguy cơ điện, lửa, giao thông. Gọi hỏi và chạm nhẹ vai; không gây đau để thử phản ứng. Nhờ người gọi 115 ngay khi không đáp ứng; nếu một mình có điện thoại, bật loa ngoài.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('b6ea45b3-8597-5688-afef-0bfcb2f1ffb2','358c7197-a3b5-5d61-b225-cc087be9800a',2,'Kiểm tra thở','Mở đường thở, kiểm tra thở không quá 10 giây. Không thở bình thường hoặc thở ngáp: gọi 115, bật loa ngoài và bắt đầu CPR phù hợp người lớn hoặc trẻ em theo hướng dẫn; không chờ tìm mạch.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('a8350ce7-7b3a-5133-9791-b4e4db63781a','358c7197-a3b5-5d61-b225-cc087be9800a',3,'Nếu vẫn thở bình thường','Nếu không nghi chấn thương, đặt nằm nghiêng an toàn. Nếu nghi chấn thương đầu/cổ, hạn chế di chuyển và làm theo tổng đài. Liên tục theo dõi thở.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'358c7197-a3b5-5d61-b225-cc087be9800a','0da603f1-f47f-5756-8179-90ff789e71f5',1,10,13,'all','Nguyên tắc an toàn và tiếp cận.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'358c7197-a3b5-5d61-b225-cc087be9800a','ff3d753d-e494-545b-9d0a-f6c3ebcda36d',2,NULL,NULL,'all','Gọi sớm, nhận biết hô hấp bất thường.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'358c7197-a3b5-5d61-b225-cc087be9800a','b8c89150-d213-59ad-8488-f081dfcf2aec',3,NULL,NULL,'all','Tư thế hồi phục và ngoại lệ chấn thương.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'358c7197-a3b5-5d61-b225-cc087be9800a','fec4959c-796a-5568-9dd2-f5cec7e945a0',4,14,22,'all','Tư thế an toàn và cấp cứu cơ bản.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'358c7197-a3b5-5d61-b225-cc087be9800a','4a32d4d5-7ba3-59f9-84db-d949bbe43e93',5,NULL,NULL,'all','Gọi cấp cứu sớm và không trì hoãn hồi sức.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('e414b8de-9284-5c4e-8369-cdab430db812','0b14f81f-ea45-5c18-9b9e-763bebedbd41','adult_cpr','adult_cpr','CPR và AED ở người lớn','ADULT','Người lớn không đáp ứng và không thở bình thường. Đây không phải bài CPR trẻ em.','Gọi 115, bật loa ngoài và bắt đầu ép tim; nhờ người tìm AED.','["Không đáp ứng, không thở hoặc chỉ thở ngáp."]'::jsonb,'["Gọi 115, bật loa ngoài và bắt đầu ép tim; nhờ người tìm AED."]'::jsonb,'["Không dừng CPR chỉ vì tiếng thở ngáp.","Không dùng độ sâu ép người lớn cho trẻ em."]'::jsonb,'["Gọi 115 ngay; không để việc tìm AED làm chậm ép tim."]'::jsonb,'DRAFT',false,NULL,1,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('7b90d60f-5aab-5728-a750-f0dac0ec3203','e414b8de-9284-5c4e-8369-cdab430db812',1,'Chuẩn bị','Đảm bảo an toàn, gọi trợ giúp. Để người bệnh nằm ngửa; bắt đầu hồi sức ngay theo tổng đài, tránh trì hoãn vì tìm mạch.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('607d54bd-d7be-5b4f-801d-561baa7a1018','e414b8de-9284-5c4e-8369-cdab430db812',2,'Ép tim','Đặt gót bàn tay ở giữa ngực, trên nửa dưới xương ức; tay kia chồng lên, đan ngón, giữ tay thẳng. Ép 5–6 cm, 100–120 lần/phút; thả ngực nảy lại hoàn toàn.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('0afbce4c-04d2-5f80-b40f-615ab6d86149','e414b8de-9284-5c4e-8369-cdab430db812',3,'Hỗ trợ thở','Nếu đã học và có thể thổi ngạt: 30 lần ép, 2 lần thổi đủ làm ngực nhô. Nếu không thể thổi: ép liên tục và nghe tổng đài.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('4668d19d-1603-5ca7-a64e-74052e7436b7','e414b8de-9284-5c4e-8369-cdab430db812',4,'Dùng AED','Bật máy khi có, dán điện cực lên ngực trần theo hình trên miếng dán. Không ai chạm người bệnh khi máy phân tích/phóng điện. Tiếp tục ép ngay theo máy.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('abc55702-209d-581d-b0f9-acc4d0547a1f','e414b8de-9284-5c4e-8369-cdab430db812',5,'Tiếp tục','Tiếp tục tới khi nhân viên y tế tiếp nhận, người bệnh có đáp ứng và thở bình thường, hoặc bạn không thể tiếp tục vì kiệt sức/nguy hiểm.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'e414b8de-9284-5c4e-8369-cdab430db812','0da603f1-f47f-5756-8179-90ff789e71f5',1,42,45,'all','Thao tác CPR người lớn.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'e414b8de-9284-5c4e-8369-cdab430db812','ff3d753d-e494-545b-9d0a-f6c3ebcda36d',2,NULL,NULL,'all','Vị trí ép, AED, gọi sớm và CPR chỉ ép khi không thể thổi.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('1ba9dcb0-aba2-5c1d-a28d-859efa70f7c4','0b14f81f-ea45-5c18-9b9e-763bebedbd41','child_cpr','child_cpr','CPR trẻ em cho người sơ cứu','CHILD','Trẻ em không đáp ứng, không thở bình thường; loại trừ nhũ nhi. Ưu tiên hướng dẫn của 115.','Gọi 115 bằng loa ngoài, nhờ người hỗ trợ; bắt đầu hồi sức.','["Trẻ không đáp ứng, không thở bình thường hoặc chỉ ngáp."]'::jsonb,'["Gọi 115 bằng loa ngoài, nhờ người hỗ trợ; bắt đầu hồi sức."]'::jsonb,'["Không áp dụng kỹ thuật nhũ nhi hoặc độ sâu 5–6 cm mặc định.","Không trì hoãn ép tim khi không thể thổi ngạt."]'::jsonb,'["Tiếp tục tới khi đội cấp cứu tiếp nhận hoặc trẻ có đáp ứng và thở bình thường."]'::jsonb,'DRAFT',false,NULL,1,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('98e191d2-ec8e-5f16-9d72-d4b3c602de83','1ba9dcb0-aba2-5c1d-a28d-859efa70f7c4',1,'Mở đường thở','Đảm bảo an toàn. Đặt nằm ngửa, mở đường thở và kiểm tra thở không quá 10 giây; không mất thời gian tìm mạch.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('6ddd79b2-3789-5e6d-bad2-5f5ba6e42bb2','1ba9dcb0-aba2-5c1d-a28d-859efa70f7c4',2,'Thổi ngạt ban đầu','Thổi 5 nhịp đầu nếu có thể: nâng cằm, ngửa đầu phù hợp, bịt mũi và áp kín miệng trẻ. Mỗi nhịp khoảng 1 giây, vừa đủ thấy ngực nhô.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('110f5392-3abd-55a4-8a60-1c899c4efce6','1ba9dcb0-aba2-5c1d-a28d-859efa70f7c4',3,'Ép ngực','Dùng một hoặc hai bàn tay theo kích thước trẻ ở nửa dưới xương ức. Ép khoảng 1/3 bề dày ngực, 100–120 lần/phút, để ngực nảy lại; không dùng độ sâu người lớn.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('f980fbd5-d16c-567f-9587-f713b09ad481','1ba9dcb0-aba2-5c1d-a28d-859efa70f7c4',4,'Tiếp tục hồi sức','Người không được đào tạo CPR nhi khoa chuyên biệt dùng 30 ép : 2 thổi; người đã học PBLS dùng 15:2 theo đào tạo. Nếu không thể thổi, vẫn ép tim và nghe 115. Dùng AED theo hướng dẫn thiết bị khi có.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'1ba9dcb0-aba2-5c1d-a28d-859efa70f7c4','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,19,26,'all','Hồi sức trẻ em, 5 nhịp đầu và tần số ép.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'1ba9dcb0-aba2-5c1d-a28d-859efa70f7c4','4a32d4d5-7ba3-59f9-84db-d949bbe43e93',2,NULL,NULL,'all','Tỉ lệ theo mức đào tạo; gọi 115 sớm khi có điện thoại.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('35917c54-3ba6-513f-96ae-3b23190e30cc','a244809f-f145-5432-a8f2-f038469f35b5','adult_choking','adult_choking','Hóc dị vật ở người lớn còn tỉnh','ADULT','Người lớn còn tỉnh; không áp dụng ép bụng cho người mang thai hoặc khi không vòng tay được quanh bụng. Xin hướng dẫn 115 cho ngoại lệ.','Ho còn hiệu quả: khuyến khích ho. Ho kém hoặc không thở được: nhờ người gọi 115.','["Đột ngột không nói, ho hiệu quả hoặc thở được khi ăn/ngậm vật."]'::jsonb,'["Ho còn hiệu quả: khuyến khích ho. Ho kém hoặc không thở được: nhờ người gọi 115."]'::jsonb,'["Không móc mù vào miệng; không cho ăn uống để đẩy dị vật.","Không tiếp tục vỗ/ép khi đã thở và ho hiệu quả."]'::jsonb,'["Không nói/ho/thở được hoặc bất tỉnh: cần cấp cứu ngay."]'::jsonb,'DRAFT',false,NULL,1,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('583467c9-fdd0-5ac7-a143-a7c204fb688d','35917c54-3ba6-513f-96ae-3b23190e30cc',1,'Khuyến khích ho','Khi còn ho mạnh và thở được, động viên ho, theo dõi; không làm thủ thuật khi ho còn hiệu quả.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('85a1c6bf-ffe2-5aa1-98ed-5f078bcee9cb','35917c54-3ba6-513f-96ae-3b23190e30cc',2,'Vỗ lưng','Ho không hiệu quả: đỡ ngực, cho cúi về trước; dùng gót bàn tay vỗ tối đa 5 lần giữa hai bả vai. Dừng khi dị vật bật ra.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('b60ebe6b-d8fc-514e-918a-ff523fb9ec9f','35917c54-3ba6-513f-96ae-3b23190e30cc',3,'Ép bụng','Nếu chưa đỡ: đứng sau, nắm tay đặt giữa rốn và mũi xương ức, tay còn lại ôm nắm tay, giật vào trong và lên trên tối đa 5 lần. Tiếp tục xen kẽ 5 vỗ lưng và 5 ép bụng khi còn tỉnh.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('5e72f9d5-bf74-58fc-849f-e7eeda428a01','35917c54-3ba6-513f-96ae-3b23190e30cc',4,'Theo dõi','Bất tỉnh: hạ nằm an toàn, gọi 115 và bắt đầu CPR. Sau ép bụng thành công vẫn cần được khám.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'35917c54-3ba6-513f-96ae-3b23190e30cc','0da603f1-f47f-5756-8179-90ff789e71f5',1,14,15,'all','Dấu hiệu và ép bụng. Văn bản trích xuất bị đảo thứ tự, đã kiểm hình trang.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'35917c54-3ba6-513f-96ae-3b23190e30cc','b8c89150-d213-59ad-8488-f081dfcf2aec',2,NULL,NULL,'all','Bổ sung quy trình vỗ lưng trước ép bụng cho tắc nặng.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('f96a8b6b-a49a-5216-bbdf-9efd7dc65481','a244809f-f145-5432-a8f2-f038469f35b5','child_choking','child_choking','Hóc dị vật ở trẻ trên 5 tuổi','CHILD','Chỉ trẻ trên 5 tuổi, còn tỉnh; không dùng cho nhũ nhi. Không mở rộng các thao tác này cho trẻ nhỏ hơn khi chưa có bài phù hợp.','Nhờ người gọi 115 nếu trẻ không ho/thở hiệu quả; không chờ trẻ tím.','["Đột ngột không ho hiệu quả, không nói/khóc hoặc không thở được."]'::jsonb,'["Nhờ người gọi 115 nếu trẻ không ho/thở hiệu quả; không chờ trẻ tím."]'::jsonb,'["Không móc miệng khi không thấy rõ dị vật.","Không dùng bài cho trẻ dưới phạm vi tuổi nêu trên."]'::jsonb,'["Khó thở tăng, không phát âm được hoặc bất tỉnh: cấp cứu ngay."]'::jsonb,'DRAFT',false,NULL,1,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('e40ad51f-b31a-559f-90c7-1b962d07ad60','f96a8b6b-a49a-5216-bbdf-9efd7dc65481',1,'Khi ho hiệu quả','Động viên trẻ ho và theo dõi. Không gây nôn, không cho ăn uống.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('369fdb8b-2894-5333-a900-8aeccabe9d85','f96a8b6b-a49a-5216-bbdf-9efd7dc65481',2,'Ho không hiệu quả','Đỡ trẻ cúi về trước, vỗ tối đa 5 lần giữa hai bả vai; kiểm tra sau mỗi lần và dừng nếu đã thông.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('67105f94-360d-5244-9832-fce31d586915','f96a8b6b-a49a-5216-bbdf-9efd7dc65481',3,'Nếu vẫn tắc','Đứng hoặc quỳ phía sau theo chiều cao trẻ. Đặt nắm tay trên rốn, dưới mũi ức; kéo vào trong và lên trên tối đa 5 lần. Xen kẽ vỗ lưng/ép bụng khi còn tỉnh.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('b7172052-df63-5f1f-80f6-45fb3d132adc','f96a8b6b-a49a-5216-bbdf-9efd7dc65481',4,'Nếu mất ý thức','Đặt trẻ nằm an toàn, bắt đầu CPR trẻ em với 5 nhịp thổi ban đầu nếu có thể và làm theo 115. Khám y tế sau sự cố dù đã đỡ.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'f96a8b6b-a49a-5216-bbdf-9efd7dc65481','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,59,63,'all','Giới hạn trên 5 tuổi theo kỹ thuật Heimlich trong tài liệu.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'f96a8b6b-a49a-5216-bbdf-9efd7dc65481','4a32d4d5-7ba3-59f9-84db-d949bbe43e93',2,NULL,NULL,'all','Đối chiếu vỗ lưng và ép bụng theo lứa tuổi.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('8d98fcdc-56a0-5937-bcf5-5e3f531edbf0','a441bbef-e3f3-5a6b-ba8a-2afbd9583954','adult_drowning','adult_drowning','Đuối nước — người lớn','ADULT','Người lớn sau tai nạn dưới nước; không tự xuống nước nếu chưa có kỹ năng cứu hộ.','Hô gọi cứu hộ và 115; đưa phao/gậy từ vị trí an toàn.','["Trẻ gặp nạn dưới nước, sau đưa lên có thể ho, khó thở hoặc không đáp ứng."]'::jsonb,'["Hô gọi cứu hộ và 115; đưa phao/gậy từ vị trí an toàn."]'::jsonb,'["Không dốc ngược/vác chạy để đổ nước; không làm chậm hồi sức.","Không dùng nguồn nhiệt nóng trực tiếp lên da."]'::jsonb,'["Gọi 115 nếu giảm ý thức, khó thở, thở bất thường hoặc cần hồi sức."]'::jsonb,'DRAFT',false,NULL,1,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('8916a30b-e818-582c-a5a7-34419c117070','8d98fcdc-56a0-5937-bcf5-5e3f531edbf0',1,'Cứu an toàn','Nhờ cứu hộ. Từ chỗ vững, đưa vật nổi hoặc gậy để hỗ trợ; không mạo hiểm xuống nước hay để người khác xuống cứu.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('a33a73b9-bb9d-52d8-8373-28c6930c0f60','8d98fcdc-56a0-5937-bcf5-5e3f531edbf0',2,'Sau đưa lên','Ở nơi an toàn trên cạn, kiểm tra đáp ứng và thở. Không thở bình thường: gọi 115, cho 5 nhịp thổi ban đầu nếu có thể rồi CPR người lớn theo tổng đài. Không trì hoãn hồi sức.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('8cf997ae-a749-5d87-bd81-44fc3aabf947','8d98fcdc-56a0-5937-bcf5-5e3f531edbf0',3,'Theo dõi và giữ ấm','Nếu còn thở, theo dõi liên tục; thay quần áo ướt khi phù hợp và phủ chăn. Nhờ đưa đi đánh giá y tế; không kết luận an toàn chỉ vì người đó tỉnh.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'8d98fcdc-56a0-5937-bcf5-5e3f531edbf0','b8c89150-d213-59ad-8488-f081dfcf2aec',1,NULL,NULL,'all','Đuối nước: an toàn cứu hộ, 5 nhịp thổi ban đầu rồi CPR, AED và giữ ấm.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'8d98fcdc-56a0-5937-bcf5-5e3f531edbf0','ff3d753d-e494-545b-9d0a-f6c3ebcda36d',2,NULL,NULL,'all','Kỹ thuật CPR người lớn sau thổi ban đầu trong đuối nước.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('1d6be1d2-a3a8-50f6-bb6e-90016a3d6d4c','a441bbef-e3f3-5a6b-ba8a-2afbd9583954','child_drowning','child_drowning','Đuối nước — trẻ em','CHILD','Trẻ em sau tai nạn dưới nước; người trợ giúp không tự xuống nước khi chưa có kỹ năng cứu hộ.','Hô gọi cứu hộ và 115; đưa phao/gậy từ vị trí an toàn.','["Trẻ gặp nạn dưới nước, sau đưa lên có thể ho, khó thở hoặc không đáp ứng."]'::jsonb,'["Hô gọi cứu hộ và 115; đưa phao/gậy từ vị trí an toàn."]'::jsonb,'["Không dốc ngược/vác chạy để đổ nước; không làm chậm hồi sức.","Không dùng nguồn nhiệt nóng trực tiếp lên da."]'::jsonb,'["Gọi 115 nếu giảm ý thức, khó thở, thở bất thường hoặc cần hồi sức."]'::jsonb,'DRAFT',false,NULL,1,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('e54a3642-4b2f-5826-afd8-1afce48d4380','1d6be1d2-a3a8-50f6-bb6e-90016a3d6d4c',1,'Cứu an toàn','Nhờ cứu hộ. Từ chỗ vững, đưa vật nổi hoặc gậy để hỗ trợ; không mạo hiểm xuống nước hay để trẻ khác xuống cứu.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('043cb4ce-18d2-5320-9e27-a3d81489311b','1d6be1d2-a3a8-50f6-bb6e-90016a3d6d4c',2,'Sau đưa lên','Ở nơi an toàn, kiểm tra đáp ứng và thở tối đa 10 giây. Không thở bình thường: bắt đầu CPR trẻ em, ưu tiên 5 nhịp thổi đầu nếu có thể; nghe 115.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('0279ef9b-2938-5ced-bcd4-556d05e181fd','1d6be1d2-a3a8-50f6-bb6e-90016a3d6d4c',3,'Theo dõi và giữ ấm','Nếu còn thở, theo dõi liên tục; thay quần áo ướt khi phù hợp và phủ chăn. Nhờ đưa đi đánh giá y tế; không kết luận an toàn chỉ vì trẻ tỉnh.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'1d6be1d2-a3a8-50f6-bb6e-90016a3d6d4c','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,105,108,'all','Cứu hộ an toàn, hồi sức và giữ ấm; không áp dụng phần nhũ nhi.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'1d6be1d2-a3a8-50f6-bb6e-90016a3d6d4c','4a32d4d5-7ba3-59f9-84db-d949bbe43e93',2,NULL,NULL,'all','Sau đuối nước: 5 nhịp thổi đầu và CPR; không trì hoãn gọi khi có điện thoại.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('8fe4f201-ed15-5b31-9737-16ec691044da','9e1d205d-5a38-580d-8c04-0ce189f9467e','shared_minor_wound','shared_minor_wound','Vết cắt nhỏ và trầy xước','ALL','Người lớn và trẻ em. Vết nông, nhỏ, không có vật cắm sâu và không chảy máu nhiều. Vết cắn, vết sâu hoặc bẩn khó làm sạch cần đánh giá riêng.','Trấn an người bị thương, làm sạch tay và cầm máu bằng gạc sạch nếu cần.','["Trầy lớp da ngoài hoặc vết cắt nhỏ."]'::jsonb,'["Trấn an người bị thương, làm sạch tay và cầm máu bằng gạc sạch nếu cần."]'::jsonb,'["Không dùng bông gòn phủ vào vết hở.","Không tự bôi kháng sinh hoặc chất lạ để thay việc làm sạch."]'::jsonb,'["Đưa đi khám khi sâu/rộng, còn bẩn, có dị vật, chảy máu không cầm hoặc dấu nhiễm trùng."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('2a1c4d53-ed2e-5d30-9997-abfe836496c5','8fe4f201-ed15-5b31-9737-16ec691044da',1,'Chuẩn bị','Rửa tay và đeo găng nếu có. Cho người bị thương ngồi, trấn an; hỗ trợ trẻ khi làm sạch và thay băng. Nếu còn chảy máu, ép bằng gạc/vải sạch.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('8c138183-dff3-5d0d-90af-4eac06ba98e3','8fe4f201-ed15-5b31-9737-16ec691044da',2,'Làm sạch','Khi máu đã kiểm soát, rửa nhẹ bằng nước sạch; làm sạch vùng da quanh vết thương. Bụi bẩn cắm sâu không tự moi lấy.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('a67ab2b4-0cf9-5911-83fe-290486cd9ef7','8fe4f201-ed15-5b31-9737-16ec691044da',3,'Che bảo vệ','Thấm khô bằng gạc sạch rồi che bằng băng phù hợp, giữ sạch và theo dõi. Cần tư vấn y tế khi đỏ/sưng/đau tăng hoặc có mủ.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'8fe4f201-ed15-5b31-9737-16ec691044da','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,50,51,'all','Mục 5.4; không đưa chỉ định bôi kháng sinh vào bài cộng đồng.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'8fe4f201-ed15-5b31-9737-16ec691044da','aa4dd01e-5118-53d9-92a7-5deed81dcf4c',2,NULL,NULL,'all','Đối chiếu làm sạch, che phủ và dấu hiệu cần khám.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('5a10b0f1-6fd8-500f-b2f7-ec13ea80dbe2','bae89c4a-8406-53b7-8c54-aa3f458a2bb1','shared_suspected_fracture','shared_suspected_fracture','Nghi gãy xương','ALL','Người lớn và trẻ em. Chấn thương chi nghi gãy; không cố tự chẩn đoán hoặc nắn xương.','Nhờ trợ giúp y tế, giữ vùng bị thương ở tư thế ít đau.','["Đau, sưng/bầm, biến dạng hoặc không cử động được sau chấn thương."]'::jsonb,'["Nhờ trợ giúp y tế, giữ vùng bị thương ở tư thế ít đau."]'::jsonb,'["Không tự di chuyển người nghi tổn thương cột sống/chậu.","Không kéo chi cho thẳng hoặc tự nắn xương."]'::jsonb,'["Gãy hở, đau dữ dội, biến dạng, chảy máu nhiều hoặc chi lạnh/tê cần cấp cứu."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('d3ae0139-cf61-5926-ae55-d5914bbbd521','5a10b0f1-6fd8-500f-b2f7-ec13ea80dbe2',1,'Giữ yên','Dừng vận động; trấn an người bệnh. Không thử bẻ/nắn để tìm tiếng lạo xạo.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('4ef59331-7582-5055-a56f-5ef1b8889109','5a10b0f1-6fd8-500f-b2f7-ec13ea80dbe2',2,'Đỡ vùng bị thương','Dùng quần áo/đệm đỡ và hạn chế cử động ở tư thế hiện có. Không cố kéo thẳng chi hoặc nhét xương lộ trở lại.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('8e2b906a-a3f4-5435-aa77-ed1782006f73','5a10b0f1-6fd8-500f-b2f7-ec13ea80dbe2',3,'Chờ trợ giúp','Nếu có chảy máu, dùng vật sạch bảo vệ/cầm máu, tránh ép lên xương lộ. Giữ bất động và làm theo nhân viên y tế.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'5a10b0f1-6fd8-500f-b2f7-ec13ea80dbe2','0da603f1-f47f-5756-8179-90ff789e71f5',1,18,19,'all','Dấu hiệu nghi gãy và hỗ trợ bất động.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'5a10b0f1-6fd8-500f-b2f7-ec13ea80dbe2','fec4959c-796a-5568-9dd2-f5cec7e945a0',2,30,35,'all','Hướng dẫn sơ cứu chung cho người lớn và trẻ em; không suy liều thuốc từ bài.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('a4784455-390d-524b-a8fd-7a75b4ccbf1a','43f5cc49-79ed-592f-9aac-ca7eb267b537','shared_sprain','shared_sprain','Nghi bong gân','ALL','Người lớn và trẻ em. Đau/sưng quanh khớp sau vặn xoắn; chưa loại trừ gãy xương. Khớp biến dạng cần xem bài trật khớp/đánh giá y tế.','Dừng hoạt động và giảm cử động vùng đau.','["Đau quanh khớp, sưng, hạn chế vận động sau chấn thương."]'::jsonb,'["Dừng hoạt động và giảm cử động vùng đau."]'::jsonb,'["Không chườm đá trực tiếp hoặc băng quá chặt.","Không coi sưng/đau là chắc chắn chỉ bong gân."]'::jsonb,'["Đi khám nếu đau nhiều, không chịu lực, biến dạng hoặc chưa rõ tổn thương."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('352e632a-5beb-5cde-a0ba-2def1e8f156f','a4784455-390d-524b-a8fd-7a75b4ccbf1a',1,'Nghỉ','Đỡ chi ở tư thế thoải mái, không cố chịu lực để thử khớp.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('965e7d0c-3d8b-5df2-9c59-b77d2b6015f5','a4784455-390d-524b-a8fd-7a75b4ccbf1a',2,'Chườm lạnh','Bọc túi lạnh bằng vải, chườm 5–10 phút theo nguồn; không áp đá trực tiếp vào da.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('8e887fad-b227-57f5-b02c-e2efc3932e2c','a4784455-390d-524b-a8fd-7a75b4ccbf1a',3,'Giảm sưng','Có thể kê cao chi và băng đỡ nhẹ nếu biết cách. Đau tăng, tê hoặc chi lạnh khi băng: nới ngay và đi khám.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'a4784455-390d-524b-a8fd-7a75b4ccbf1a','0da603f1-f47f-5756-8179-90ff789e71f5',1,20,21,'all','RICE; giữ đúng thời gian chườm của nguồn, không tự mở rộng.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'a4784455-390d-524b-a8fd-7a75b4ccbf1a','fec4959c-796a-5568-9dd2-f5cec7e945a0',2,69,70,'all','Bối cảnh chấn thương ở trẻ và chuyển đánh giá y tế; thao tác tại chỗ dùng PNT2024, không tự nắn.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('96b84301-e630-5fed-acc2-f78909831cd0','43f5cc49-79ed-592f-9aac-ca7eb267b537','shared_dislocation','shared_dislocation','Nghi trật khớp','ALL','Người lớn và trẻ em. Khớp đau/biến dạng sau va chạm hoặc ngã; không tự chỉnh khớp.','Giữ yên khớp, gọi trợ giúp y tế.','["Khớp biến dạng, đau và khó vận động sau chấn thương."]'::jsonb,'["Giữ yên khớp, gọi trợ giúp y tế."]'::jsonb,'["Không tự nắn, kéo hoặc bẻ khớp.","Không tiếp tục vận động vì nghĩ khớp sẽ tự vào lại."]'::jsonb,'["Cần đánh giá y tế sớm; tê, lạnh chi hoặc đau dữ dội cần cấp cứu."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('77ed92db-b960-5c6a-8a67-5de018152f7a','96b84301-e630-5fed-acc2-f78909831cd0',1,'Trấn an','Dừng vận động và đỡ vùng bị thương ở tư thế ít đau.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('1849c2e9-c6f7-5337-a031-996f370690b1','96b84301-e630-5fed-acc2-f78909831cd0',2,'Bất động','Đệm, đỡ khớp trong tư thế hiện tại. Không thử dấu lò xo hay kéo nắn để kiểm tra.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('543c4e24-e7fa-535c-96ad-7d72be4b6cee','96b84301-e630-5fed-acc2-f78909831cd0',3,'Liên hệ y tế','Gọi 115 hoặc nhờ trợ giúp đưa đi đánh giá; giữ khớp bất động trong lúc chờ.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'96b84301-e630-5fed-acc2-f78909831cd0','0da603f1-f47f-5756-8179-90ff789e71f5',1,22,23,'all','Nhận biết và xử trí trật khớp, loại thao tác thử dấu khám chuyên môn.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'96b84301-e630-5fed-acc2-f78909831cd0','fec4959c-796a-5568-9dd2-f5cec7e945a0',2,69,70,'all','Bối cảnh chấn thương ở trẻ và chuyển đánh giá y tế; thao tác tại chỗ dùng PNT2024, không tự nắn.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('80f87c2e-d9a9-5608-a792-756d8e0c281f','259a716e-249c-5f43-8ed1-3b7ef2953268','shared_head_spine','shared_head_spine','Nghi chấn thương đầu, cổ hoặc cột sống','ALL','Người lớn và trẻ em. Sau ngã cao/tai nạn; ưu tiên gọi y tế và hạn chế di chuyển. Không hướng dẫn tự nẹp cổ chuyên dụng.','Gọi 115; giữ người bị thương yên và quan sát thở.','["Đau đầu/cổ/lưng, thay đổi ý thức hoặc yếu/tê sau tai nạn."]'::jsonb,'["Gọi 115; giữ người bị thương yên và quan sát thở."]'::jsonb,'["Không tự buộc dây quanh cổ hoặc làm thủ thuật nẹp chưa được đào tạo.","Không cho ăn uống khi nghi chấn thương nặng."]'::jsonb,'["Giảm ý thức, nôn, co giật, yếu/tê hoặc thở bất thường: cấp cứu ngay."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('c905c081-ea70-5329-927b-e3abb5f83bb0','80f87c2e-d9a9-5608-a792-756d8e0c281f',1,'An toàn và gọi','Loại nguy cơ hiện trường nếu có thể, nhờ gọi 115. Không vội bế, kéo hoặc đưa người bị thương đi khi không có nguy hiểm trực tiếp.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('ccbafd39-160c-52e2-8de8-26ccd29f3f40','80f87c2e-d9a9-5608-a792-756d8e0c281f',2,'Hạn chế di chuyển','Khuyến khích nằm yên; không vặn cổ/lưng hoặc kéo ngồi dậy. Không rút dị vật hay ấn vào vùng sọ bị hở.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('d5b70ee3-cc98-5dfa-95b6-9653f4130bdd','80f87c2e-d9a9-5608-a792-756d8e0c281f',3,'Theo dõi','Quan sát ý thức và thở. Nếu đường thở bị đe dọa hoặc không thở bình thường, báo tổng đài và làm theo hướng dẫn; đường thở luôn được ưu tiên.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'80f87c2e-d9a9-5608-a792-756d8e0c281f','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,13,14,'all','Cột sống, tư thế và ngoại lệ chấn thương.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'80f87c2e-d9a9-5608-a792-756d8e0c281f','fec4959c-796a-5568-9dd2-f5cec7e945a0',2,68,70,'all','Tai nạn/ngã: tránh di động trẻ.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'80f87c2e-d9a9-5608-a792-756d8e0c281f','b8c89150-d213-59ad-8488-f081dfcf2aec',3,NULL,NULL,'all','Ưu tiên đường thở, hạn chế vận động cổ.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('0c04a405-4ffb-5f7c-b2b2-439495df58da','9e48989b-4824-5b64-bee6-afcc95de49a4','shared_electrical_injury','shared_electrical_injury','Điện giật: an toàn trước khi tiếp cận','ALL','Người lớn và trẻ em gặp điện giật. Đường điện cao thế/dây rơi cần đơn vị điện lực xử lý.','Không chạm nạn nhân khi chưa ngắt điện; gọi 115 và điện lực khi cần.','["Tiếp xúc điện, có thể bỏng, ngã, mất ý thức hoặc thở bất thường."]'::jsonb,'["Không chạm nạn nhân khi chưa ngắt điện; gọi 115 và điện lực khi cần."]'::jsonb,'["Không túm kéo người còn tiếp xúc điện.","Không cho ăn uống trước đánh giá y tế."]'::jsonb,'["Gọi 115 khi mất ý thức, khó thở, bỏng hoặc chấn thương; không coi tỉnh lại là hết nguy cơ."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('30952612-d90a-5db6-b196-67cf69689412','0c04a405-4ffb-5f7c-b2b2-439495df58da',1,'Cắt điện an toàn','Ngắt nguồn bằng cầu dao/thiết bị an toàn nếu tiếp cận được. Với điện cao thế/dây rơi, giữ xa và chờ điện lực; không dùng gậy để tự xử lý.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('2e7aeedf-0677-5634-8d57-af0c428cd0eb','0c04a405-4ffb-5f7c-b2b2-439495df58da',2,'Chỉ tiếp cận khi an toàn','Kiểm tra đáp ứng và thở. Không thở bình thường: CPR theo hướng dẫn 115; chú ý khả năng chấn thương do ngã.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('23b4de57-cdd1-5c24-ac77-62d406fcf46a','0c04a405-4ffb-5f7c-b2b2-439495df58da',3,'Theo dõi và chuyển viện','Che vùng bỏng bằng vật sạch; không bóc quần áo dính. Đề nghị đánh giá y tế sau điện giật, theo dõi thở trong lúc chờ.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'0c04a405-4ffb-5f7c-b2b2-439495df58da','0da603f1-f47f-5756-8179-90ff789e71f5',1,38,41,'all','An toàn nguồn điện, ABC và theo dõi.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'0c04a405-4ffb-5f7c-b2b2-439495df58da','fec4959c-796a-5568-9dd2-f5cec7e945a0',2,85,86,'all','Không tiếp xúc trực tiếp, đường điện lớn phải nhờ điện lực.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('c36bb404-ecec-5a1f-9179-e8b2bdbf945e','e972a118-8bdf-5238-8676-40112f2dc43e','shared_heat_illness','shared_heat_illness','Say nóng và nghi sốc nhiệt','ALL','Người lớn và trẻ em sau tiếp xúc nóng.','Ưu tiên làm mát.','["Mệt/chóng mặt; lú lẫn hoặc co giật là dấu nặng."]'::jsonb,'["Đưa tới chỗ mát và làm mát ngay."]'::jsonb,'["Chỉ cho uống nước khi tỉnh và nuốt được."]'::jsonb,'["Gọi 115 nếu chưa đỡ sau 30 phút; không chờ khi có dấu nặng."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('3875951a-38a1-516c-9f4d-d7b9247a3cd5','c36bb404-ecec-5a1f-9179-e8b2bdbf945e',1,'Nghỉ mát','Nới quần áo, nghỉ nơi thoáng.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('0b90115a-7f00-5e1c-97ef-f677ed4384cd','c36bb404-ecec-5a1f-9179-e8b2bdbf945e',2,'Làm mát','Lau/phun nước mát và quạt. Túi lạnh phải bọc vải.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('6ef2fe5c-58fd-55bc-9fe1-3b383e4457eb','c36bb404-ecec-5a1f-9179-e8b2bdbf945e',3,'Gọi trợ giúp','Lú lẫn, co giật, bất tỉnh: gọi 115 ngay.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'c36bb404-ecec-5a1f-9179-e8b2bdbf945e','1733c1c6-b69a-5000-a6d6-b6fc1399e340',1,NULL,NULL,'all','Nguồn ngoài hai PDF; bản web không có số trang.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('f4aaec4e-0339-5d35-82e3-b3e025a0411d','86719c2e-923a-558f-bbbd-309e81b86c63','shared_stroke','shared_stroke','Dấu hiệu nghi đột quỵ','ALL','Người lớn và trẻ em. Triệu chứng thần kinh xuất hiện đột ngột; bài nhận biết và gọi cấp cứu, không phân loại đột quỵ.','Gọi 115 ngay, ghi thời điểm bắt đầu hoặc lần cuối còn bình thường.','["Đột ngột méo mặt, yếu tay/chân, nói khó; có thể mất thăng bằng hoặc thay đổi thị lực."]'::jsonb,'["Gọi 115 ngay, ghi thời điểm bắt đầu hoặc lần cuối còn bình thường."]'::jsonb,'["Không chờ triệu chứng tự hết hoặc chờ đủ giờ vàng.","Không tự cho aspirin, thuốc hạ áp, ăn hoặc uống.","FAST không bao quát mọi dấu hiệu. Đột ngột giảm ý thức, yếu liệt, rối loạn thị lực hoặc đau đầu dữ dội cũng cần cấp cứu, kể cả ở trẻ em."]'::jsonb,'["Dấu hiệu nghi đột quỵ dù thoáng qua cũng cần trợ giúp khẩn."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('e76a788f-bed2-521e-bb60-76d1d8dfcf0c','f4aaec4e-0339-5d35-82e3-b3e025a0411d',1,'Nhận biết','Yêu cầu cười, nâng hai tay và nói một câu đơn giản nếu làm được; bất thường đột ngột cần gọi 115 ngay.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('80bb3920-10bf-55f9-8ad7-2354d65985fe','f4aaec4e-0339-5d35-82e3-b3e025a0411d',2,'Chờ hỗ trợ','Trấn an, để ở vị trí an toàn, thoải mái; không để tự lái xe hoặc đi lại.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('de3f8adb-ae4f-5d70-b0a3-d6ae38d56488','f4aaec4e-0339-5d35-82e3-b3e025a0411d',3,'Theo dõi thở','Giảm ý thức, nôn hoặc thở bất thường: báo tổng đài và làm theo hướng dẫn. Không thở bình thường: CPR.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'f4aaec4e-0339-5d35-82e3-b3e025a0411d','0da603f1-f47f-5756-8179-90ff789e71f5',1,31,33,'all','Đã đọc hình BE FAST, không chỉ dựa vào text extraction.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'f4aaec4e-0339-5d35-82e3-b3e025a0411d','b8c89150-d213-59ad-8488-f081dfcf2aec',2,NULL,NULL,'all','FAST và gọi cấp cứu; không tự dùng thuốc.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'f4aaec4e-0339-5d35-82e3-b3e025a0411d','281f6bf4-7b86-595e-a5c7-35ae2827676a',3,NULL,NULL,'all','Đột quỵ có thể xảy ra ở mọi tuổi; dấu hiệu đột ngột cần cấp cứu, không chỉ dựa vào FAST để loại trừ.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('0a36c34e-7c2a-5e7c-abff-81018ad31a12','264d76d4-90db-57f7-b8ad-f18364caf371','shared_seizure','shared_seizure','Co giật','ALL','Người lớn và trẻ em đang co giật; không tự chẩn đoán nguyên nhân hoặc hướng dẫn thuốc/liều. Không bao gồm nhũ nhi.','Bảo vệ và theo dõi.','["Co cứng/giật người, giảm ý thức."]'::jsonb,'["Dọn nguy hiểm, ghi giờ bắt đầu."]'::jsonb,'["Không ăn uống khi chưa tỉnh hoàn toàn."]'::jsonb,'["Gọi 115 khi lần đầu, quá 5 phút, lặp cơn không tỉnh, chấn thương nặng hoặc khó thở."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('aa266a52-8195-5b3d-a4e8-2119a38f1364','0a36c34e-7c2a-5e7c-abff-81018ad31a12',1,'Bảo vệ','Đệm mềm dưới đầu.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('68055c6b-d210-5859-8ea6-2b47f3ea37fb','0a36c34e-7c2a-5e7c-abff-81018ad31a12',2,'Giữ an toàn','Chỉ di chuyển khỏi nguy hiểm; không nhét vật vào miệng.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('b45fb79f-0c09-568d-9db6-9925ea153990','0a36c34e-7c2a-5e7c-abff-81018ad31a12',3,'Sau cơn','Hết giật, kiểm tra thở; còn thở đặt nằm nghiêng. Không thở bình thường: gọi 115, CPR.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'0a36c34e-7c2a-5e7c-abff-81018ad31a12','5a0d539b-236c-517c-a7aa-01cd35ed23e3',1,NULL,NULL,'all','Hai PDF chỉ nhắc co giật trong bối cảnh khác, không có bài sơ cứu độc lập.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('8e0fe544-f4b8-5d8c-838c-d4b98260b568','e99fb7ee-2f77-5cf6-b978-187d7c857a31','shared_anaphylaxis','shared_anaphylaxis','Nghi phản vệ','ALL','Người lớn và trẻ em. Phản ứng nhanh sau thức ăn, thuốc hoặc côn trùng; cần xử trí y tế khẩn.','Gọi 115 ngay, nói nghi phản vệ.','["Khó thở/khàn tiếng, phù môi/lưỡi, choáng/ngất; có thể kèm mề đay hoặc đau bụng."]'::jsonb,'["Gọi 115 ngay, nói nghi phản vệ."]'::jsonb,'["Không dùng thuốc kháng histamin để thay cấp cứu phản vệ.","Không tự thử lại thức ăn/thuốc nghi gây dị ứng."]'::jsonb,'["Khó thở, phù họng/lưỡi, ngất hoặc giảm ý thức: gọi cấp cứu ngay."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('cb851bd9-466b-51fb-be81-c8a6f5566999','8e0fe544-f4b8-5d8c-838c-d4b98260b568',1,'Ngừng tiếp xúc','Ngừng tác nhân nghi gây dị ứng nếu làm được an toàn, không làm chậm gọi cấp cứu.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('85b0eb42-6ee7-5a6f-828e-84b2f4ab576e','8e0fe544-f4b8-5d8c-838c-d4b98260b568',2,'Tư thế và thuốc đã được kê','Cho nằm; khó thở có thể nâng vai hoặc ngồi từ từ, duỗi chân. Nếu có bút adrenaline đã được kê, hỗ trợ dùng theo chỉ dẫn thiết bị/đào tạo và 115; không tự pha tiêm.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('69c2ee24-4a78-5e8a-b5af-cfda4485d02c','8e0fe544-f4b8-5d8c-838c-d4b98260b568',3,'Theo dõi','Không cho đứng/đi lại dù đỡ. Theo dõi ý thức và thở; không thở bình thường thì CPR. Cần đánh giá tại bệnh viện ngay.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'8e0fe544-f4b8-5d8c-838c-d4b98260b568','0da603f1-f47f-5756-8179-90ff789e71f5',1,24,24,'all','Dấu hiệu và ngừng dị nguyên, gọi 115.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'8e0fe544-f4b8-5d8c-838c-d4b98260b568','f0816a1e-aaa7-58d0-a439-800adeb6f694',2,NULL,NULL,'all','Tư thế và hỗ trợ dùng bút đã kê; không tư vấn liều.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('297764ce-ff2c-5e1e-9121-e431ff94d63b','8f234c49-a546-5259-b864-482f9dd05ae0','shared_suspected_poisoning','shared_suspected_poisoning','Nghi ngộ độc','ALL','Người lớn và trẻ em. Nghi nuốt/uống thuốc, hóa chất, nấm hoặc chất độc; không gồm xử trí thuốc đặc hiệu hay kê liều.','Gọi 115/nhân viên y tế ngay; không chờ có triệu chứng.','["Có phơi nhiễm nghi ngờ; có thể đau bụng/nôn, buồn ngủ, khó thở hoặc co giật."]'::jsonb,'["Gọi 115/nhân viên y tế ngay; không chờ có triệu chứng."]'::jsonb,'["Không móc họng/gây nôn; không tự dùng than hoạt, thuốc hoặc dung dịch trung hòa.","Không tin đã hết độc chỉ vì nôn/đau bụng tạm giảm."]'::jsonb,'["Nghi nuốt/uống thuốc, hóa chất hoặc chất độc: gọi 115 hoặc đến cấp cứu ngay; không chờ triệu chứng xuất hiện."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('3ce057eb-89dd-5074-bce8-5ad8ca45cefc','297764ce-ff2c-5e1e-9121-e431ff94d63b',1,'Ngừng phơi nhiễm','Đưa khỏi nguy cơ nếu an toàn; không tự vào khu vực khí độc. Không cho ăn uống hoặc tự gây nôn.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('2dace64a-4d04-5cfe-bfbd-fe334e08742e','297764ce-ff2c-5e1e-9121-e431ff94d63b',2,'Chuẩn bị thông tin','Giữ bao bì/tên chất, thời điểm và lượng nghi tiếp xúc nếu biết, không trì hoãn cấp cứu để tìm đủ thông tin.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('4c51a523-a9a0-5b60-83c5-bb34c5b2f1f4','297764ce-ff2c-5e1e-9121-e431ff94d63b',3,'Theo dõi','Theo dõi thở và ý thức. Giảm ý thức còn thở: tư thế an toàn nếu không chấn thương. Không thở bình thường: CPR phù hợp người lớn hoặc trẻ em và nghe 115.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'297764ce-ff2c-5e1e-9121-e431ff94d63b','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,75,81,'all','Chọn nhận biết và chuyển viện; không dùng các đoạn gây nôn/than hoạt/thuốc liều.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'297764ce-ff2c-5e1e-9121-e431ff94d63b','b0d755f4-64f2-576c-80ce-f17522c06c4e',2,NULL,NULL,'all','Nguồn quyết định không gây nôn, không cho ăn uống và giữ bao bì.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('1225b40a-08f4-5973-a746-8cc98f48a39b','5489c849-0a1e-5b07-bec6-6720401a4098','shared_dog_bite','shared_dog_bite','Chó cắn','ALL','Người lớn và trẻ em. Vết cắn gây rách da; cần đánh giá dự phòng dại và uốn ván, không chờ theo dõi con vật mới đi khám.','Ra khỏi vùng nguy hiểm; rửa sớm và đến cơ sở y tế.','["Vết cắn/xước do chó, có thể chảy máu."]'::jsonb,'["Ra khỏi vùng nguy hiểm; rửa sớm và đến cơ sở y tế."]'::jsonb,'["Không nặn vết thương, đắp lá/chất lạ hoặc băng kín.","Không tự quyết định bỏ tiêm dự phòng vì chó nhà."]'::jsonb,'["Vết sâu, vùng mặt/cổ hoặc chảy máu nặng: trợ giúp khẩn; mọi vết cắn rách da cần đánh giá y tế."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('c903258d-4196-5109-8f57-8f146aab6754','1225b40a-08f4-5973-a746-8cc98f48a39b',1,'An toàn','Tránh bị cắn tiếp; không tự bắt con vật. Nếu máu chảy nhiều, dùng vật sạch cầm máu và gọi trợ giúp.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('b558aead-66ff-525c-9e5a-18e57d826e19','1225b40a-08f4-5973-a746-8cc98f48a39b',2,'Rửa vết thương','Rửa với xà phòng và nước chảy liên tục 15 phút khi tình trạng cho phép.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('4ef34e0f-2aff-5528-8467-9f8c18fc14a6','1225b40a-08f4-5973-a746-8cc98f48a39b',3,'Đi khám ngay','Đến cơ sở y tế để đánh giá tiêm phòng dại/uốn ván và xử trí vết thương. Không chờ xuất hiện triệu chứng.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'1225b40a-08f4-5973-a746-8cc98f48a39b','0da603f1-f47f-5756-8179-90ff789e71f5',1,25,26,'all','Rửa 15 phút và đánh giá dự phòng; bỏ đoạn số liệu không cần cho thao tác.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'1225b40a-08f4-5973-a746-8cc98f48a39b','fec4959c-796a-5568-9dd2-f5cec7e945a0',2,92,93,'all','Chăm sóc vết cắn ở trẻ; dự phòng dại đối chiếu WHO, không đồng nhất huyết thanh kháng dại với uốn ván.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'1225b40a-08f4-5973-a746-8cc98f48a39b','081b4a2d-d4a1-5ac3-8dd5-6e7304aecd05',3,NULL,NULL,'all','Dự phòng sau phơi nhiễm cho mọi lứa tuổi; rửa xà phòng/nước ít nhất 15 phút và đi khám ngay.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('c6a48804-f4ab-5349-918b-d89dd420a1dd','5489c849-0a1e-5b07-bec6-6720401a4098','shared_snake_bite','shared_snake_bite','Nghi rắn cắn','ALL','Người lớn và trẻ em. Mọi nghi ngờ rắn cắn cần đánh giá khẩn; không yêu cầu người dùng xác định họ rắn.','Ra xa rắn, gọi 115 và hạn chế vận động.','["Bị rắn cắn, có thể đau/sưng hoặc chưa có dấu hiệu rõ."]'::jsonb,'["Ra xa rắn, gọi 115 và hạn chế vận động."]'::jsonb,'["Không kết luận rắn lành chỉ dựa vào vết răng hoặc chưa sưng.","Không làm theo mẹo hút nọc/đắp thuốc."]'::jsonb,'["Tất cả trường hợp nghi rắn cắn cần đến cơ sở y tế sớm; khó thở, yếu hoặc chảy máu bất thường cần 115."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('bc632086-2c7e-562d-8238-9a2c27c9b450','c6a48804-f4ab-5349-918b-d89dd420a1dd',1,'Giữ yên','Trấn an; giữ chi bị cắn yên, tháo trang sức/quần áo chật trước khi sưng.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('4833b119-75bc-500a-abe6-e0ee1e812c51','c6a48804-f4ab-5349-918b-d89dd420a1dd',2,'Không làm thủ thuật','Không rạch, hút nọc, garô, nặn hoặc bôi thuốc. Không tự băng ép theo họ rắn khi chưa nhận diện và chưa được đào tạo.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('be5b22e5-c244-55aa-ae18-09acd2cc6fd4','c6a48804-f4ab-5349-918b-d89dd420a1dd',3,'Chuyển viện','Nhờ trợ giúp vận chuyển, hạn chế tự đi bộ. Không bắt rắn hoặc trì hoãn để chụp/nhận dạng.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'c6a48804-f4ab-5349-918b-d89dd420a1dd','0da603f1-f47f-5756-8179-90ff789e71f5',1,27,28,'all','Giới hạn biện pháp theo họ rắn; không tự lựa chọn băng ép.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'c6a48804-f4ab-5349-918b-d89dd420a1dd','fec4959c-796a-5568-9dd2-f5cec7e945a0',2,94,95,'all','Theo dõi mọi vết cắn; không garô, rạch, hút.');
INSERT INTO articles(id,category_id,slug,variant_key,title,age_group,applies_to,summary,recognition_json,quick_actions_json,warnings_json,seek_help_json,status,content_checked,checked_at,content_revision,updated_at) VALUES ('a52772d7-0b94-54ca-9795-8e0142138e0d','5489c849-0a1e-5b07-bec6-6720401a4098','shared_bee_sting','shared_bee_sting','Ong đốt','ALL','Người lớn và trẻ em bị ong đốt; dấu toàn thân hoặc phù vùng miệng/cổ cần cấp cứu.','Đưa người bị đốt xa khu vực có ong, theo dõi khó thở.','["Đau, ngứa, sưng tại chỗ; dấu nặng gồm khó thở, choáng, nổi mề đay toàn thân."]'::jsonb,'["Đưa người bị đốt xa khu vực có ong, theo dõi khó thở."]'::jsonb,'["Không bóp/nặn, gãi hoặc đắp chất lạ.","Không tự bôi thuốc để trì hoãn đánh giá khi có dấu hiệu nặng."]'::jsonb,'["Khó thở, phù vùng đầu mặt cổ hoặc choáng: gọi 115 ngay."]'::jsonb,'DRAFT',false,NULL,2,'2026-10-28T00:00:00Z'::timestamptz);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('b9fef2dd-7872-5600-8d3c-931e83c905c9','a52772d7-0b94-54ca-9795-8e0142138e0d',1,'Tránh bị đốt tiếp','Đưa tới nơi an toàn; không chọc phá tổ hoặc đuổi bắt ong.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('81ca36b5-fba8-545a-9937-66c1377e86e9','a52772d7-0b94-54ca-9795-8e0142138e0d',2,'Chăm sóc tại chỗ','Nếu ngòi còn thấy rõ, khều nhẹ để lấy ra, không bóp túi nọc. Rửa bằng nước và xà phòng, chườm lạnh qua vải.',NULL,NULL,NULL);
INSERT INTO article_steps(id,article_id,position,title,instruction,asset_key,image_url,alt_text) VALUES ('c72c2ca3-4a1a-540e-a838-99fca5c8d2e1','a52772d7-0b94-54ca-9795-8e0142138e0d',3,'Theo dõi','Khó thở, mệt/lạnh tay chân, mề đay lan rộng hoặc nhiều vết đốt: tìm trợ giúp ngay. Tiểu ít/đỏ cũng cần khám.',NULL,NULL,NULL);
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'a52772d7-0b94-54ca-9795-8e0142138e0d','fec4959c-796a-5568-9dd2-f5cec7e945a0',1,93,94,'all','Côn trùng đốt và dấu hiệu cần trợ giúp.');
INSERT INTO article_references(id,article_id,source_id,position,page_start,page_end,section_key,note) VALUES (gen_random_uuid(),'a52772d7-0b94-54ca-9795-8e0142138e0d','0da603f1-f47f-5756-8179-90ff789e71f5',2,29,30,'all','Theo dõi nhiều vết đốt/dấu toàn thân; loại phần tự dùng thuốc.');
